class TimeReadCsvNamesDtype:
    def setup(self, cache, shape, names, dtype):
        # ray init
        if ASV_USE_IMPL == "modin":
            IMPL.DataFrame([])
        file_id = self._get_file_id(shape, dtype)
        self.filename, self.names, self.dtype = cache[file_id]

